189	        // Locking the sheet first, so two users opening the same claim's editor at once take turns.
190	        sheets.lockForNumbering(sheetId);
191	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
192	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusRefusedException();
