231	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason) {
232	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
233	        // once no other open on the sheet is under way; a refusal rolls the number back.
234	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
235	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
236	        String action = switch (next) {
237	            case OPEN -> "open";
238	            case SETTLED -> "settle";
239	            case VOID -> "void";
240	            default -> throw new ClaimStatusRefusedException();
241	        };
242	        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
243	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
244	        if (voidingSettled) refuseVoidOfSettled(sheetId, user, claim);
245	        else if (!claim.getStatus().canBecome(next)) {
246	            throw new ClaimStatusRefusedException();
247	        }
248	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
249	            throw new ClaimDeferredException();
250	        }
251	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
252	            throw new ClaimSettledByOpenerException();
253	        }
254	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
255	        // Settling freezes the late charge of the moment into the settled due.
256	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
257	        if (next == ClaimStatus.SETTLED) refuseUnproved(sheetId, person, claim, settling);
258	        if (next == ClaimStatus.OPEN) refuseUnnoted(sheetId, claim, chargedFigureOf(sheetId, person, claim));
259	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
260	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonForVoid(sheetId, reason) : null;
261	        RollupService.Snapshot before = rollup.snapshot(sheetId);
262	        refuseIfClosed(sheetId, claim.getDueBy());
263	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
264	        switch (next) {
265	            case OPEN -> {
266	                number(numbering, claim);
267	                claim.setOpenedBy(user.strip());
268	            }
269	            case SETTLED -> {
270	                claim.setSettledDue(settling);
271	                claim.setSettleBatch(null);
272	            }
273	            case PENDING -> claim.setSettleBatch(null);
274	            case VOID -> claim.setVoidReason(voidReason);
275	            default -> {}
276	        }
277	        claim.setStatus(next);
278	        logStatus(sheetId, user, person, claim);
279	        Claim saved = claims.saveAndFlush(claim);
280	        String event = switch (next) {
281	            case OPEN -> "CLAIM_OPENED";
282	            case PENDING -> "CLAIM_PENDING";
283	            case SETTLED -> "CLAIM_SETTLED";
284	            case VOID -> "CLAIM_VOIDED";
285	            case DRAFT, DELETED -> throw new IllegalStateException();
286	        };
287	        String due = next == ClaimStatus.SETTLED
288	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
289	                : voidingSettled ? " reversed=" + figureText(saved.getSettledDue())
290	                : "";
291	        if (voidReason != null) due += " reason=" + voidReason;
292	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
293	        if (next == ClaimStatus.SETTLED) notifyWatchers(sheetId, user, person, saved);
294	        rollup.recordChanges(sheetId, user, before);
295	        return saved;
296	    }
