298	    /**
299	     * Delete a DRAFT claim: DELETED, it counts nowhere and cannot be edited, opened or voided until restored.
300	     * Refused for a claim in any other status, one another user's editor locks, or one due inside a closed period.
301	     */
302	    @Transactional
303	    public Claim delete(String sheetId, String user, Long id) {
304	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
305	        RollupService.Snapshot before = rollup.snapshot(sheetId);
306	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
307	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) throw new ClaimStatusRefusedException();
308	        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
309	        refuseIfClosed(sheetId, claim.getDueBy());
310	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
311	        claim.setLockedBy(null);
312	        claim.setStatus(ClaimStatus.DELETED);
313	        logStatus(sheetId, user, person, claim);
314	        Claim saved = claims.saveAndFlush(claim);
315	        record("CLAIM_DELETED", sheetId, user, person, saved);
316	        rollup.recordChanges(sheetId, user, before);
317	        return saved;
318	    }
