331	        refuseIfClosed(sheetId, claim.getDueBy());
332	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
333	        claim.setStatus(ClaimStatus.DRAFT);
