379	    /**
380	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
381	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
382	     * late charge as of today). Refused for anyone
383	     * else, a claim in any other status, or one due inside a closed period.
384	     */
385	    @Transactional
386	    public Claim resettle(String sheetId, String user, Long id) {
387	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
388	        RollupService.Snapshot before = rollup.snapshot(sheetId);
389	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
390	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
391	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
392	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
393	        refuseIfClosed(sheetId, claim.getDueBy());
394	        BigDecimal old = claim.getSettledDue();
395	        BigDecimal figure = floored(sheetId, claim, LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim),
396	                sheets.today(sheetId), graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d),
397	                roundingOf(sheetId, claim)));
398	        claim.setSettledDue(figure);
399	        logStatus(sheetId, user, person, claim);
400	        Claim saved = claims.saveAndFlush(claim);
401	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
402	                " old=" + figureText(old) + " new=" + figureText(figure));
403	        notifyWatchers(sheetId, user, person, saved);
404	        rollup.recordChanges(sheetId, user, before);
405	        return saved;
406	    }
