408	    /**
409	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
410	     * statement stays bound; its period, which follows its due-by, stays too. While the sheet numbers by
411	     * period and the claim was numbered within another period, it takes the next number of its due-by's
412	     * period, its old number never given again. Refused for anyone else, a claim in any other status, one
413	     * due inside a closed period, or a new date after its person's retirement date.
414	     */
415	    @Transactional
416	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
417	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
418	        Sheet numbering = sheets.lockForNumbering(sheetId);
419	        RollupService.Snapshot before = rollup.snapshot(sheetId);
420	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
421	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
422	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
423	        refuseIfClosed(sheetId, claim.getDueBy());
424	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
425	        if (!person.mayClaimOn(date)) throw new PersonRetiredException();
426	        LocalDate old = claim.getDate();
427	        String oldPeriod = claim.getNumberPeriod() != null ? claim.getNumberPeriod() : periodOn(sheetId, claim.getDueBy());
428	        claim.setDate(date);
429	        if (numbering.numbersByPeriod() && !oldPeriod.equals(periodOn(sheetId, claim.getDueBy()))) {
430	            if (claim.getNumberPeriod() != null) {
431	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
432	            }
433	            number(numbering, claim);
434	        }
435	        Claim saved = claims.saveAndFlush(claim);
436	        record("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
437	        rollup.recordChanges(sheetId, user, before);
438	        return saved;
439	    }
