480	    /**
481	     * Reassign a claim by the rules above; a bulk move ({@code bulk}) takes a claim already its new
482	     * person's as moved to them again rather than refusing it.
483	     */
484	    @Transactional
485	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean bulk) {
486	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
487	        Sheet numbering = sheets.lockForNumbering(sheetId);
488	        RollupService.Snapshot before = rollup.snapshot(sheetId);
489	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
490	        ClaimStatus status = claim.getStatus();
491	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
492	        if (!settings.mayDo(sheetId, user, "reassign")) throw new ClaimNotPermittedException();
493	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
494	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
495	        if (!bulk && from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
496	        refuseIfClosed(sheetId, claim.getDueBy());
497	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
498	        claim.unstate(sheets.today(sheetId));
499	        claim.moveTo(to.getId(), claims.nextListed());
500	        if (claim.getNumber() != null) {
501	            if (claim.getNumberPeriod() != null) {
502	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
503	            }
504	            number(numbering, claim);
505	        }
506	        Claim saved = claims.saveAndFlush(claim);
507	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
508	                " from=" + from.getName() + " to=" + to.getName());
509	        rollup.recordChanges(sheetId, user, before);
510	        return saved;
511	    }
