516	    /**
517	     * Split an amount (more than 0.00 and less than its amount) off an OPEN claim, by a user whose role may
518	     * open a claim. The claim keeps the rest of its amount and loses any figure a statement bound it to; the
519	     * new claim is OPEN with the split-off amount, the same date and note, the sheet's next number, opened
520	     * by the user, with its due-by fixed now from the terms in force on the date, and names the original's
521	     * number as split from, a late entry when its due-by falls in a soft-closed period. Refused for a claim
522	     * not OPEN, a deferred one, or one due inside a closed period (judged by the original alone).
523	     */
524	    @Transactional
525	    public Split split(String sheetId, String user, Long id, BigDecimal amount) {
526	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
527	        Sheet numbering = sheets.lockForNumbering(sheetId);
528	        RollupService.Snapshot before = rollup.snapshot(sheetId);
529	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
530	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
531	        if (claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimDeferredException();
532	        if (!settings.mayDo(sheetId, user, "open")) throw new ClaimNotPermittedException();
533	        refuseIfClosed(sheetId, claim.getDueBy());
534	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitRefusedException();
535	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
536	        LocalDate on = claim.getDate();
537	        claim.setAmount(claim.getAmount().subtract(amount));
538	        claim.unstate(sheets.today(sheetId));
539	        Claim original = claims.saveAndFlush(claim);
540	        int terms = termsOf(sheetId, person, on);
541	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
542	        Claim split = new Claim(sheetId, person.getId(), amount, on, original.getNote(), dueBy, terms);
543	        split.setSplitFrom(original.getNumber());
544	        split.setTags(original.getTags());
545	        split.setLateEntry(periods.softClosedOn(sheetId, dueBy));
546	        number(numbering, split);
547	        split.setOpenedBy(user.strip());
548	        split.setEditedBy(original.getEditedBy());
549	        split.setStatus(ClaimStatus.OPEN);
550	        split = claims.saveAndFlush(split);
551	        logStatus(sheetId, user, person, split);
552	        split = claims.saveAndFlush(split);
553	        record("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
554	        record("CLAIM_OPENED", sheetId, user, person, split);
555	        rollup.recordChanges(sheetId, user, before);
556	        return new Split(original, split);
557	    }
