760	    /** What a rate preview finds: how many claims' dues would change, and by how much in all. */
761	    public record RatePreview(int count, BigDecimal diff) {}
762	
763	    /**
764	     * How many OPEN and PENDING claims of people on the grade (the one in force on the claim's date) would show
765	     * a different due were the percent the grade's rate on every date, and the sum of new minus current dues
766	     * (a due of n/a counts as 0). A claim bound by a statement does not change. Nothing is stored.
767	     */
768	    @Transactional(readOnly = true)
769	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
770	        int count = 0;
771	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
772	        Map<Long, Person> byId = new HashMap<>();
773	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) byId.put(p.getId(), p);
774	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
775	            if (!claim.getStatus().isOpen() || claim.isBound()) continue;
776	            Person person = byId.get(claim.getPersonId());
777	            if (person == null || !grade.equals(person.gradeOn(claim.getDate()))) continue;
778	            BigDecimal current = chargedFigureOf(sheetId, person, claim);
779	            BigDecimal figure = claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
780	            BigDecimal next = charged(sheetId, person, claim, figure);
781	            BigDecimal was = current == null ? BigDecimal.ZERO.setScale(2) : current;
782	            BigDecimal now = next == null ? BigDecimal.ZERO.setScale(2) : next;
783	            if (current == null || now.compareTo(was) != 0) {
784	                count++;
785	                diff = diff.add(now.subtract(was));
786	            }
787	        }
788	        return new RatePreview(count, diff.setScale(2));
789	    }
