791	    /** The claim's due with the figure given: floored, with its late charge while overdue; a settled due as fixed. */
792	    private BigDecimal charged(String sheetId, Person person, Claim claim, BigDecimal figure) {
793	        if (claim.getSettledDue() != null) return claim.getSettledDue();
794	        return floored(sheetId, claim, LateCharge.withCharge(claim, figure, sheets.today(sheetId),
795	                graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim)));
796	    }
