803	    /** The due at least the sheet's floor in force on the claim's date, unless a correction; null when none. */
804	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
805	        if (due == null || claim.isCorrection()) return due;
806	        return due.max(settings.floorOn(sheetId, claim.getDate()));
