809	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
810	    private RoundingMode roundingOf(String sheetId, Claim claim) {
811	        LocalDate basis = Rounding.basisOf(claim,
812	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
813	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
