816	    /**
817	     * A claim's rate figure: its amount times the rate on its date of its person's grade in force on it, rounded to
818	     * cents as {@link Rounding} has it, with no floor; null with no rate.
819	     */
820	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
821	        RoundingMode rounding = roundingOf(sheetId, claim);
822	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
823	                .map(Rate::getPct)
824	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
825	                .orElse(null);
826	    }
