866	     * Number afresh, on the sheet (locked for numbering by the caller), the claims that had a number before
867	     * ({@code oldNumbers}, by claim id): each takes the sheet's next, in the order they were opened (by the
868	     * sheet's today each was first opened on, then in the order they were added). A correction, or a claim
869	     * split off another, then names the number its claim was given.
870	     */
871	    @Transactional
872	    public void numberAfresh(Sheet to, List<Claim> numbering, Map<Long, String> oldNumbers) {
873	        List<Claim> numbered = numbering.stream().filter(c -> oldNumbers.get(c.getId()) != null)
874	                .sorted(Comparator.comparing(Claim::openedOn,
875	                        Comparator.nullsFirst(Comparator.naturalOrder()))
876	                        .thenComparing(Claim::getId))
877	                .toList();
878	        Map<String, String> renumbered = new HashMap<>();
879	        for (Claim claim : numbered) {
880	            number(to, claim);
881	            claims.saveAndFlush(claim);
882	            renumbered.put(oldNumbers.get(claim.getId()), claim.getNumber());
883	        }
884	        for (Claim claim : numbering) {
885	            if (claim.getCorrects() != null) {
886	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
887	            }
888	            if (claim.getSplitFrom() != null) {
889	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
890	            }
891	        }
892	        claims.saveAllAndFlush(numbering);
893	    }
894	
895	    /** Keep each of the claim's tags among those ever used on the sheet. */
896	    private void keepTags(String sheetId, Claim claim) {
897	        keepTags(sheetId, claim.getTags());
898	    }
899	
900	    /** Keep each of the tags (a claim's or a person's) among those ever used on the sheet. */
901	    @Transactional
902	    public void keepTags(String sheetId, List<String> tagged) {
903	        for (String tag : tagged) {
904	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) tags.save(new ClaimTag(sheetId, tag));
905	        }
906	    }
907	
908	    /** Refuse a reference (null: none) that a claim on the sheet other than this one (null: any) already carries. */
909	    private void refuseIfRefUsed(String sheetId, Long self, String ref) {
910	        if (ref == null) return;
911	        claims.findBySheetIdAndRefKey(sheetId, Claim.refKeyOf(ref))
912	                .filter(other -> !other.getId().equals(self))
913	                .ifPresent(other -> { throw new DuplicateClaimRefException(); });
914	    }
915	
916	    /**
917	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
918	     * one but is not a correction.
919	     */
920	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
921	        if (amount.signum() >= 0) {
922	            if (corrects != null) throw new CorrectionRefusedException();
923	            return;
924	        }
925	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
926	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
927	        if (!settled) throw new CorrectionRefusedException();
928	    }
929	
930	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
931	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
932	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
933	        BigDecimal limit = settings.clerkLimit(sheetId);
934	        return limit != null && due != null && due.compareTo(limit) > 0;
935	    }
936	
937	    /** Refuse a change to a claim whose due-by falls inside a closed period; the caller holds the sheet's lock. */
938	    private void refuseIfClosed(String sheetId, LocalDate date) {
939	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
940	    }
941	
942	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
943	        return date != null ? date : sheets.today(sheetId);
944	    }
945	
946	    /** A new claim's date: the one given, else the entry date while set, else the sheet's today. */
947	    private LocalDate dateOrEntryDate(String sheetId, LocalDate date) {
948	        if (date != null) return date;
949	        LocalDate entryDate = settings.entryDate(sheetId);
950	        return entryDate != null ? entryDate : sheets.today(sheetId);
951	    }
952	}
